\documentclass[tikz,border=10pt]{standalone}
\usepackage{pgfplots}
\usepackage{ctex} % 支持中文
\pgfplotsset{compat=1.18}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    xlabel={年份},
    ylabel={毕业人数（万人）},
    title={近五年中国高校毕业生人数变化趋势},
    grid=major,
    xmin=2018.5, xmax=2023.5,
    ymin=800, ymax=1200,
    xtick={2019,2020,2021,2022,2023},
    ytick={800,850,900,950,1000,1050,1100,1150,1200},
    legend pos=north west,
    legend style={font=\small},
    label style={font=\large},
    title style={font=\huge},
    tick label style={font=\large},
    width=12cm,
    height=8cm,
    mark options={scale=1.5}
]

% 绘制折线图
\addplot[
    color=blue,
    mark=square,
    line width=2pt,
    nodes near coords,
    every node near coord/.append style={
        font=\small,
        yshift=5pt
    }
] coordinates {
    (2019, 834)
    (2020, 874)
    (2021, 909)
    (2022, 1076)
    (2023, 1158)
};

% 添加图例
\legend{高校毕业生人数}

\end{axis}
\end{tikzpicture}
